#!/usr/bin/env bash
# PARROT // GHOST BSPWM v4  •  tema original ligero para Parrot OS y VMware
# Instalador independiente. No ejecuta scripts remotos, ni elimina el escritorio actual.
set -Eeuo pipefail

LEAN=0
NO_CLEAN=0
FULL_UPGRADE=0
CONFIG_ONLY=0
EFFECTS=0
EXTRAS=0
for opt in "$@"; do
  case "$opt" in
    --full-upgrade) FULL_UPGRADE=1 ;;
    --config-only) CONFIG_ONLY=1 ;;
    --effects) EFFECTS=1 ;;
    --tools) EXTRAS=1 ;;
    --lean) LEAN=1 ;;
    --no-clean) NO_CLEAN=1 ;;
    -h|--help)
      cat <<'HELP'
Uso:
  bash instalar_ghost_oggun_v4_1_lite.sh
  bash instalar_ghost_oggun_v4_1_lite.sh --full-upgrade
  bash instalar_ghost_oggun_v4_1_lite.sh --config-only
  bash instalar_ghost_oggun_v4_1_lite.sh --effects
  bash instalar_ghost_oggun_v4_1_lite.sh --tools

Sin opciones: apt update + instala bspwm, sxhkd, Polybar, Rofi, Feh, terminal
 y fondo IRON FORGE incluido. No cambia tu sesión actual.
 --full-upgrade : opcional, usa parrot-upgrade para actualización completa.
 --config-only  : configura el escritorio sin usar APT (si ya está instalado).
 --effects      : activa Picom (efectos suaves opcionales; apagados por defecto).
 --tools        : herramientas de estudio adicionales (btop, tmux, etc.).
 --lean         : revisar y confirmar retirada de herramientas opcionales.
 --no-clean     : no limpiar caché APT ni miniaturas antiguas y temporales vencidos.
 Por defecto incluye herramientas esenciales y PDF de estudio.
HELP
      exit 0 ;;
    *) printf 'Opción no reconocida: %s\n' "$opt" >&2; exit 2 ;;
  esac
done

[[ "$(id -u)" -ne 0 ]] || { echo 'Ejecuta como usuario normal, SIN sudo delante.' >&2; exit 1; }
[[ -n "${HOME:-}" && -d "$HOME" ]] || { echo 'No se encontró HOME.' >&2; exit 1; }
command -v python3 >/dev/null || { echo 'Falta python3.' >&2; exit 1; }
ROOT="$HOME/.config"
CYBER="$ROOT/ghost-bspwm"
BACKUP="$HOME/bspwm-backups/$(date +%Y%m%d-%H%M%S)-$$"
LOG="$HOME/bspwm-v4_1-$(date +%Y%m%d-%H%M%S).log"
WALL_DIR="$HOME/Pictures/GhostBSPWM"
BIN="$HOME/.local/bin"
mkdir -p "$BACKUP" "$WALL_DIR" "$BIN" "$CYBER"
exec > >(tee -a "$LOG") 2>&1
trap 'echo "[ERROR] Fallo en línea $LINENO. Registro: $LOG. Respaldos: $BACKUP" >&2' ERR
say() { printf '\033[1;32m[GHOST OGGUN]\033[0m %s\n' "$*"; }
warn() { printf '\033[1;33m[AVISO]\033[0m %s\n' "$*" >&2; }
backup_file() {
  local f="$1" relative
  [[ -e "$f" || -L "$f" ]] || return 0
  relative="${f#"$HOME"/}"
  mkdir -p "$BACKUP/$(dirname "$relative")"
  cp -a -- "$f" "$BACKUP/$relative"
  say "Respaldado: ~/$relative"
}

say 'Preparando Parrot GHOST BSPWM v4. Tu escritorio actual no se elimina.'
if (( !CONFIG_ONLY )); then
  command -v apt-get >/dev/null || { echo 'Requiere Parrot/Debian con APT.' >&2; exit 1; }
  command -v sudo >/dev/null || { echo 'Falta sudo.' >&2; exit 1; }
  say 'Comprobando sudo...'
  sudo -v
  say 'Actualizando índices de paquetes (necesita Internet en VMware)...'
  if ! sudo apt-get update; then
    echo 'No se pudo actualizar. Configura VMware > Network Adapter > NAT, Connected y Connect at power on.' >&2
    exit 1
  fi
  if (( FULL_UPGRADE )); then
    if command -v parrot-upgrade >/dev/null; then
      say 'Actualización completa con parrot-upgrade...'
      sudo parrot-upgrade
    else
      warn 'No se encuentra parrot-upgrade: se omite actualización completa.'
    fi
  fi
  # Sin --no-install-recommends para network-manager: respetamos dependencias habituales.
  say 'Instalando escritorio ligero y utilidades gráficas...'
  packages=(bspwm sxhkd polybar rofi feh xfce4-terminal thunar dunst librsvg2-bin
            x11-xserver-utils fonts-dejavu-core kitty xdg-user-dirs xdg-utils xpdf
            bash python3 python3-pip python3-venv nmap wireshark openvpn git curl ca-certificates
            openssh-client ncat inetutils-telnet inetutils-ftp smbclient redis-tools iputils-ping iproute2
            tmux firefox-esr)
  if (( EFFECTS )); then packages+=(picom); fi
  if (( EXTRAS )); then packages+=(git curl nmap btop tmux neovim dnsutils); fi
  sudo env DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends "${packages[@]}"
  if ! command -v code >/dev/null; then
    say 'Instalando VS Code desde el distribuidor oficial de Microsoft.'
    case "$(dpkg --print-architecture)" in
      amd64) vscode_arch=linux-deb-x64 ;;
      arm64) vscode_arch=linux-deb-arm64 ;;
      *) vscode_arch='' ;;
    esac
    if [[ -n "$vscode_arch" ]]; then
      vscode_tmp="$(mktemp -d)"
      if curl --fail --location --proto '=https' --proto-redir '=https' --retry 2           "https://update.code.visualstudio.com/latest/$vscode_arch/stable" -o "$vscode_tmp/code.deb"; then
        chmod 755 "$vscode_tmp"
        chmod 644 "$vscode_tmp/code.deb"
        if ! sudo apt-get install -y "$vscode_tmp/code.deb"; then warn 'VS Code no se pudo instalar; instala desde https://code.visualstudio.com/download'; fi
      else warn 'No se pudo descargar VS Code; instala desde https://code.visualstudio.com/download'; fi
      rm -f -- "$vscode_tmp/code.deb"; rmdir -- "$vscode_tmp"
    else warn 'Arquitectura no contemplada para VS Code; instala manualmente.'; fi
  fi
  # Marca los paquetes elegidos como manuales para preservar su uso.
  sudo apt-mark manual "${packages[@]}" >/dev/null
  if (( LEAN )); then
    say 'Revisando herramientas opcionales instaladas (sin eliminar automáticamente).'
    candidates=(parrot-tools-full metasploit-framework beef-xss armitage sqlmap nikto hydra john hashcat aircrack-ng reaver bully wifite ettercap-graphical maltego burpsuite zaproxy)
    installed=()
    for pkg in "${candidates[@]}"; do
      if [[ "$(dpkg-query -W -f='${db:Status-Status}' "$pkg" 2>/dev/null || true)" == installed ]]; then installed+=("$pkg"); fi
    done
    if ((${#installed[@]})); then
      printf 'Candidatos: %s\n' "${installed[*]}"
      printf '%s\n' 'Se eliminan paquetes, no sus configuraciones personales. No se ejecuta autoremove automáticamente.'
      if plan=$(LC_ALL=C apt-get -s remove "${installed[@]}"); then
        printf '%s\n' "$plan"
        # Rechaza planes que retiren componentes esenciales o paquetes conservados.
        unsafe=0
        while read -r pkg; do
          [[ -z "$pkg" ]] && continue
          case "$pkg" in bash|python3*|nmap|wireshark*|tshark|libwireshark*|openvpn|git|curl|ca-certificates|openssh*|ncat|inetutils-*|smbclient|redis-tools|iproute2|iputils-ping|tmux|firefox*|code|bspwm|sxhkd|polybar|rofi|feh|kitty|xfce4-terminal|thunar|dunst|picom|xorg*|xserver*|x11-*|xdg-*|xpdf|network-manager*|systemd*|sudo|apt|dpkg|linux-image*|parrot-core*|parrot-desktop*|lightdm*|sddm*|gdm*|plasma*|mate-*|xfce4*|libc6) unsafe=1; printf 'Protegido: %s\n' "$pkg";; esac
          for keep in "${packages[@]}"; do [[ "$pkg" != "$keep" ]] || unsafe=1; done
        done < <(awk '/^Remv / {split($2,a,":");print a[1]}' <<< "$plan")
        if (( unsafe )); then warn 'Plan contiene componentes protegidos; retirada cancelada.'
        elif [[ -t 0 ]]; then
          read -r -p 'Escribe ELIMINAR para aceptar este plan: ' answer
          if [[ "$answer" == ELIMINAR ]]; then sudo apt-get remove "${installed[@]}"; else say 'Retirada omitida.'; fi
        else warn 'Sin terminal interactiva; retirada omitida.'; fi
      else warn 'No se pudo simular la retirada; no se cambia nada.'; fi
    else say 'No hay candidatos de la lista instalados.'; fi
    say 'Paquetes huérfanos: solo simulación. Revisa antes de eliminar.'
    sudo apt-get -s autoremove || true
  fi
  if (( !NO_CLEAN )); then
    say 'Limpiando caché de paquetes y miniaturas antiguas, sin tocar documentos ni registros.'
    sudo apt-get clean
    if command -v systemd-tmpfiles >/dev/null; then
      sudo systemd-tmpfiles --clean --prefix=/tmp --prefix=/var/tmp || warn "No se pudo completar la limpieza de temporales según las reglas del sistema."
    fi
  fi

fi

if (( CONFIG_ONLY )); then
  if (( LEAN )); then warn "--lean no elimina paquetes en modo --config-only."; fi
  for cmd in bspwm sxhkd polybar rofi feh xfce4-terminal; do
    command -v "$cmd" >/dev/null || { echo "Falta $cmd. Ejecuta el instalador sin --config-only." >&2; exit 1; }
  done
fi

# Respalda exactamente los archivos que el instalador va a sobrescribir.
for f in \
 "$ROOT/bspwm/bspwmrc" \
 "$ROOT/sxhkd/sxhkdrc" \
 "$ROOT/polybar/config.ini" \
 "$ROOT/rofi/ghost.rasi" \
 "$CYBER/start-polybar.sh" \
 "$CYBER/show-my-ip.sh" \
 "$CYBER/show-target.sh" \
 "$CYBER/show-vpn.sh" \
 "$CYBER/move-window.sh" \
 "$CYBER/Xresources" \
 "$CYBER/use-picom" \
 "$CYBER/kitty.conf" \
 "$CYBER/power-menu.sh" \
 "$WALL_DIR/iron-forge.jpg" \
 "$BIN/target" \
 "$BIN/Target" \
 "$BIN/mi-ip" \
 "$BIN/ghost-terminal" \
 "$BIN/ghost-study" \
 "$WALL_DIR/ghost.svg" \
 "$WALL_DIR/ghost.png"; do backup_file "$f"; done

mkdir -p "$ROOT/bspwm" "$ROOT/sxhkd" "$ROOT/polybar" "$ROOT/rofi"

# Estado: IP objetivo (validación Python) e IP del host (configuración manual opcional).
cat > "$BIN/target" <<'TARGET_EOF'
#!/usr/bin/env bash
set -Eeuo pipefail
state="$HOME/.config/ghost-bspwm"
mkdir -p "$state"
umask 077
if [[ $# -eq 0 || "${1:-}" == '-h' || "${1:-}" == '--help' ]]; then
  echo 'Uso: target <IP> [nombre] | target clear | target show'
  exit 0
fi
if [[ $# -gt 2 ]]; then echo 'Uso: target IP [nombre]' >&2; exit 2; fi
case "$1" in
  show)
    if [[ -s "$state/target-ip" ]]; then printf 'Target: %s\n' "$(cat "$state/target-ip")"; else echo 'Target: --'; fi ;;
  clear|off|-c)
    rm -f -- "$state/target-ip" "$state/target-name"
    echo 'Target eliminado de la barra.' ;;
  *)
    python3 - "$1" <<'PY'
import ipaddress, sys
try: ipaddress.ip_address(sys.argv[1])
except ValueError: sys.exit('IP no válida; ejemplo: target 10.10.11.25')
PY
    tmp="$(mktemp "$state/.target.XXXXXX")"
    printf '%s\n' "$1" > "$tmp"
    mv -f -- "$tmp" "$state/target-ip"
    if [[ -n "${2:-}" ]]; then printf '%s\n' "$2" | tr -cd '[:alnum:] _.-' | cut -c1-24 > "$state/target-name"; else rm -f "$state/target-name"; fi
    printf 'Target: %s (se verá a la derecha de Polybar)\n' "$1" ;;
esac
TARGET_EOF
chmod 755 "$BIN/target"
ln -sf target "$BIN/Target"  # Admite tanto 'target 1.2.3.4' como 'Target 1.2.3.4'.

cat > "$BIN/mi-ip" <<'HOST_EOF'
#!/usr/bin/env bash
set -Eeuo pipefail
state="$HOME/.config/ghost-bspwm"
mkdir -p "$state"
umask 077
if [[ $# -ne 1 ]]; then
  echo 'Uso: mi-ip <IPv4-del-PC-Windows> | mi-ip auto | mi-ip show'
  exit 2
fi
case "$1" in
  auto|clear) rm -f -- "$state/pc-ip"; echo 'La barra vuelve a detectar la IP de Parrot automáticamente.' ;;
  show) [[ ! -s "$state/pc-ip" ]] || { printf 'IP PC: %s\n' "$(cat "$state/pc-ip")"; exit 0; }; echo 'Modo automático: IP de Parrot.' ;;
  *)
    python3 - "$1" <<'PY'
import ipaddress, sys
try: ipaddress.IPv4Address(sys.argv[1])
except ValueError: sys.exit('IP IPv4 no válida. Ejemplo: mi-ip 192.168.1.40')
PY
    tmp="$(mktemp "$state/.pcip.XXXXXX")"
    printf '%s\n' "$1" > "$tmp"
    mv -f -- "$tmp" "$state/pc-ip"
    printf 'IP de tu PC guardada: %s\n' "$1" ;;
esac
HOST_EOF
chmod 755 "$BIN/mi-ip"

cat > "$CYBER/show-my-ip.sh" <<'IP_EOF'
#!/usr/bin/env bash
set -u
state="$HOME/.config/ghost-bspwm"
if [[ -s "$state/pc-ip" ]]; then
  printf 'PC %s\n' "$(cat "$state/pc-ip")"
  exit 0
fi
# IP asignada al invitado VMware. No es necesariamente la IP del Windows anfitrión.
iface="$(ip -4 route show default 2>/dev/null | awk 'NR==1 {print $5}')"
ipval=''
if [[ -n "$iface" ]]; then
  ipval="$(ip -o -4 addr show dev "$iface" scope global 2>/dev/null | awk 'NR==1 {split($4,a,"/"); print a[1]}')"
fi
if [[ -z "$ipval" ]]; then
  ipval="$(ip -o -4 addr show scope global 2>/dev/null | awk '$2!="lo" {split($4,a,"/"); print a[1]; exit}')"
fi
printf 'IP %s\n' "${ipval:---}"
IP_EOF
cat > "$CYBER/show-target.sh" <<'TARGETSHOW_EOF'
#!/usr/bin/env bash
state="$HOME/.config/ghost-bspwm"
if [[ -s "$state/target-ip" ]]; then
  printf 'TARGET %s%s\n' "$(cat "$state/target-ip")" "$(if [[ -s "$state/target-name" ]]; then printf ' · %s' "$(cat "$state/target-name")"; fi)"
else
  printf 'Target <IP>\n'
fi
TARGETSHOW_EOF
cat > "$CYBER/show-vpn.sh" <<'VPN_EOF'
#!/usr/bin/env bash
vpn="$(ip -o -4 addr show scope global 2>/dev/null | awk '$2 ~ /^(tun|tap|wg)[0-9]/ {split($4,a,"/"); print a[1]; exit}')"
if [[ -n "$vpn" ]]; then printf '%%{F#39FF88}VPN %s%%{F-}\n' "$vpn"; else printf '%%{F#E27979}VPN OFF%%{F-}\n'; fi
VPN_EOF
chmod 755 "$CYBER/show-my-ip.sh" "$CYBER/show-target.sh" "$CYBER/show-vpn.sh"

cat > "$BIN/ghost-terminal" <<'TERM_EOF'
#!/usr/bin/env bash
if [[ ${GHOST_TERMINAL:-kitty} == kitty ]] && command -v kitty >/dev/null; then exec kitty --config "$HOME/.config/ghost-bspwm/kitty.conf" "$@"; fi
if command -v xfce4-terminal >/dev/null; then exec xfce4-terminal "$@"; fi
if command -v xterm >/dev/null; then exec xterm "$@"; fi
echo 'No hay terminal instalada.' >&2
exit 1
TERM_EOF
chmod 755 "$BIN/ghost-terminal"

say 'Creando barra IRON FORGE...'
cat > "$CYBER/kitty.conf" <<'KITTY_EOF'
font_family DejaVu Sans Mono
font_size 11
background #080D0A
foreground #DCE8DF
cursor #39FF88
selection_background #1E5B39
selection_foreground #FFFFFF
color0 #080D0A
color1 #E27979
color2 #39FF88
color3 #E9B86A
color4 #79A8D8
color5 #A8A0CA
color6 #79DCC8
color7 #DCE8DF
color8 #60746A
color9 #FF9C9C
color10 #74FFA8
color11 #FFD28A
color12 #A8CBFF
color13 #C5B9E9
color14 #A1F1E0
color15 #FFFFFF
window_padding_width 9
background_opacity 1.0
KITTY_EOF
cat > "$CYBER/power-menu.sh" <<'POWER_EOF'
#!/usr/bin/env bash
choice=$(printf 'Cancelar\nCerrar sesion BSPWM\n' | rofi -dmenu -i -p 'Sesion' -theme "$HOME/.config/rofi/ghost.rasi") || exit 0
[[ "$choice" != 'Cerrar sesion BSPWM' ]] || bspc quit
POWER_EOF
chmod 755 "$CYBER/power-menu.sh"
cat > "$ROOT/polybar/config.ini" <<'POLYBAR_EOF'
[colors]
bg = #F21A1F24
fg = #DCE8DF
muted = #75887D
accent = #39FF88
steel = #24352C
alert = #E27979
amber = #E9B86A

[bar/base]
height = 30
radius = 15
fixed-center = true
background = ${colors.bg}
foreground = ${colors.fg}
offset-y = 8
padding-left = 1
padding-right = 1
module-margin = 1
font-0 = DejaVu Sans Mono:size=9;2
override-redirect = true
wm-restack = bspwm
enable-ipc = true

[bar/left]
inherit = bar/base
width = 40%
offset-x = 1%
modules-left = launcher cpu memory disk myip study

[bar/center]
inherit = bar/base
width = 16%
offset-x = 42%
modules-center = bspwm

[bar/right]
inherit = bar/base
width = 40%
offset-x = 59%
modules-right = vpn target date power

[module/launcher]
type = custom/text
content = ◆
content-foreground = ${colors.accent}
click-left = rofi -show drun -theme ~/.config/rofi/ghost.rasi

[module/study]
type = custom/text
content = LIBRO
content-foreground = ${colors.accent}
click-left = ~/.local/bin/ghost-study

[module/cpu]
type = internal/cpu
interval = 2
label = CPU %percentage%%
label-foreground = ${colors.fg}

[module/memory]
type = internal/memory
interval = 3
label = RAM %gb_used%
label-foreground = ${colors.fg}

[module/disk]
type = internal/fs
mount-0 = /
interval = 30
label-mounted = DSK %free%
label-mounted-foreground = ${colors.fg}

[module/myip]
type = custom/script
exec = ~/.config/ghost-bspwm/show-my-ip.sh
interval = 5
label = %output%
format-foreground = ${colors.accent}

[module/vpn]
type = custom/script
exec = ~/.config/ghost-bspwm/show-vpn.sh
interval = 3
label = %output%

[module/target]
type = custom/script
exec = ~/.config/ghost-bspwm/show-target.sh
interval = 2
label = %output:0:25:...%
format-foreground = ${colors.amber}

[module/bspwm]
type = internal/bspwm
pin-workspaces = true
enable-click = true
label-focused = ●
label-focused-foreground = ${colors.accent}
label-focused-padding = 1
label-occupied = ●
label-occupied-foreground = ${colors.fg}
label-occupied-padding = 1
label-empty = ·
label-empty-foreground = ${colors.muted}
label-empty-padding = 1
label-urgent = !
label-urgent-foreground = ${colors.alert}

[module/date]
type = internal/date
interval = 5
date = %H:%M
label = %date%
label-foreground = ${colors.fg}

[module/power]
type = custom/text
content = ⏻
content-foreground = ${colors.alert}
click-left = ~/.config/ghost-bspwm/power-menu.sh
POLYBAR_EOF

cat > "$CYBER/start-polybar.sh" <<'START_EOF'
#!/usr/bin/env bash
# Solo funciona dentro de la sesión bspwm; no toca otras sesiones de escritorio.
if ! command -v polybar >/dev/null; then exit 0; fi
pkill -u "$(id -u)" -x polybar 2>/dev/null || true
sleep 0.4
config="$HOME/.config/polybar/config.ini"
width=$(xrandr --current 2>/dev/null | awk '/current/ {for(i=1;i<=NF;i++) if($i=="current") {print $(i+1);exit}}')
if [[ "$width" =~ ^[0-9]+$ ]] && (( width < 1500 )); then
  config="$HOME/.config/ghost-bspwm/polybar-compact.ini"
  sed -e 's/modules-left = launcher cpu memory disk myip study/modules-left = launcher memory myip study/' -e 's/size=9;2/size=8;2/' -e 's/%output:0:25:...%/%output:0:18:...%/' "$HOME/.config/polybar/config.ini" > "$config"
fi
for bar in left center right; do
  polybar --quiet -c "$config" "$bar" >> "$HOME/.config/ghost-bspwm/polybar.log" 2>&1 &
done
START_EOF
chmod 755 "$CYBER/start-polybar.sh"

say 'Configurando bspwm, atajos y ahorro de recursos...'
cat > "$ROOT/bspwm/bspwmrc" <<'BSPWM_EOF'
#!/usr/bin/env bash
# Se ejecuta SOLAMENTE al seleccionar la sesión Ghost BSPWM en el login.
export PATH="$HOME/.local/bin:$PATH"
if [[ "$(bspc query -D --names | paste -sd ' ' -)" != "1 2 3 4 5 6 7 8 9 0" ]]; then
  bspc monitor -d 1 2 3 4 5 6 7 8 9 0
fi
bspc config top_padding 48
bspc config border_width 2
bspc config window_gap 9
bspc config split_ratio 0.53
bspc config focused_border_color '#39FF88'
bspc config normal_border_color '#1A1F24'
bspc config active_border_color '#60746A'
bspc config presel_feedback_color '#1E5B39'
bspc config pointer_modifier mod4
bspc config pointer_action1 move
bspc config pointer_action2 resize_side
bspc config pointer_action3 resize_corner
bspc rule -a 'Pavucontrol' state=floating center=true
bspc rule -a 'Rofi' state=floating center=true
if pgrep -u "$(id -u)" -x sxhkd >/dev/null; then pkill -USR1 -u "$(id -u)" -x sxhkd || true; else sxhkd -c "$HOME/.config/sxhkd/sxhkdrc" & fi
if command -v xsetroot >/dev/null; then xsetroot -cursor_name left_ptr; fi
if command -v feh >/dev/null && [[ -s "$HOME/Pictures/GhostBSPWM/iron-forge.jpg" ]]; then
  feh --no-fehbg --bg-fill "$HOME/Pictures/GhostBSPWM/iron-forge.jpg" &
fi
# Desactivado salvo que instalases con --effects.
if [[ -e "$HOME/.config/ghost-bspwm/use-picom" ]] && command -v picom >/dev/null; then
  picom --backend xrender --no-fading --daemon || true
fi
if command -v dunst >/dev/null; then (pgrep -u "$(id -u)" -x dunst >/dev/null || dunst) & fi
"$HOME/.config/ghost-bspwm/start-polybar.sh" &
BSPWM_EOF
chmod 755 "$ROOT/bspwm/bspwmrc"

cat > "$CYBER/move-window.sh" <<'MOVE_EOF'
#!/usr/bin/env bash
case "${1:-}" in
 north) dx=0; dy=-60;; south) dx=0; dy=60;; west) dx=-60; dy=0;; east) dx=60; dy=0;; *) exit 2;;
esac
if bspc query -N -n focused.floating >/dev/null 2>&1; then
  bspc node -v "$dx" "$dy"
else
  bspc node -s "$1.local" 2>/dev/null || true
fi
MOVE_EOF
chmod 755 "$CYBER/move-window.sh"

cat > "$ROOT/sxhkd/sxhkdrc" <<'SXHKD_EOF'
# Tecla SUPER = Windows. GHOST BSPWM.
super + {t,Return}
    ~/.local/bin/ghost-terminal
super + d
    rofi -show drun -theme ~/.config/rofi/ghost.rasi
super + e
    thunar
super + b
    ~/.local/bin/ghost-study
super + q
    bspc node -c
super + {Up,Down,Left,Right}
    ~/.config/ghost-bspwm/move-window.sh {north,south,west,east}
super + ctrl + {Up,Down,Left,Right}
    bspc node -f {north,south,west,east}.local
super + f
    bspc node -t '~fullscreen'
super + shift + space
    bspc node -t '~floating'
super + {h,j,k,l}
    bspc node -f {west,south,north,east}
super + shift + r
    bspc wm -r
super + shift + e
    bspc quit
SXHKD_EOF
for n in {1..9} 0; do
  printf 'super + %s\n    bspc desktop -f %s\n' "$n" "$n" >> "$ROOT/sxhkd/sxhkdrc"
  printf 'super + shift + %s\n    bspc node -d %s\n' "$n" "$n" >> "$ROOT/sxhkd/sxhkdrc"
done

cat > "$ROOT/rofi/ghost.rasi" <<'ROFI_EOF'
configuration {
  modi: "drun,run,window";
  show-icons: true;
  font: "monospace 11";
}
* {
  bg: #080D0A;
  fg: #DCE8DF;
  selected: #1E5B39;
  accent: #39FF88;
}
window {
  background-color: @bg;
  border: 2px;
  border-color: @accent;
  border-radius: 12px;
  width: 43%;
  padding: 14px;
}
mainbox { spacing: 10px; }
inputbar { padding: 9px; background-color: #1A1F24; children: [prompt, entry]; }
prompt { text-color: @accent; }
entry { text-color: @fg; }
listview { lines: 7; columns: 1; fixed-height: true; }
element { padding: 8px; }
element selected { background-color: @selected; }
element-text { text-color: @fg; }
ROFI_EOF

cat > "$CYBER/Xresources" <<'XR_EOF'
XTerm*background: #080D0A
XTerm*foreground: #DCE8DF
XTerm*cursorColor: #39FF88
XR_EOF

