WALL_DATA

if (( EFFECTS )); then touch "$CYBER/use-picom"; else rm -f "$CYBER/use-picom"; fi

if (( !CONFIG_ONLY )); then
  temp_desktop="$(mktemp)"
  cat > "$temp_desktop" <<'DESKTOP_EOF'
[Desktop Entry]
Name=GHOST OGGUN (bspwm)
Comment=Entorno minimalista bspwm con barra IP y Target
Exec=/usr/bin/bspwm
TryExec=/usr/bin/bspwm
Type=Application
DesktopNames=bspwm
DESKTOP_EOF
  sudo install -Dm644 "$temp_desktop" /usr/share/xsessions/parrot-ghost-bspwm.desktop
  rm -f "$temp_desktop"
fi

# PATH persistente para Bash y Zsh; no toca alias ni elimina personalizaciones.
for shellrc in "$HOME/.bashrc" "$HOME/.zshrc"; do
  backup_file "$shellrc"
  if [[ ! -f "$shellrc" ]] || ! grep -Fq '# GHOST_BSPWM_PATH' "$shellrc"; then
    cat >> "$shellrc" <<'RC_EOF'

# GHOST_BSPWM_PATH - permite usar target y mi-ip desde la terminal.
export PATH="$HOME/.local/bin:$PATH"
RC_EOF
  fi
  if ! grep -Fq '# GHOST_OGGUN_PROMPT' "$shellrc"; then
    if [[ "$shellrc" == "$HOME/.bashrc" ]]; then
      cat >> "$shellrc" <<'PROMPT_EOF'

# GHOST_OGGUN_PROMPT - solo en terminal interactiva BSPWM
if [[ $- == *i* && ${DESKTOP_SESSION:-} == *bspwm* ]]; then
  PS1='\[\e[38;5;46m\][\u@iron-forge]\[\e[0m\]-[\w]\n\[\e[38;5;46m\]❯\[\e[0m\] '
fi
PROMPT_EOF
    else
      cat >> "$shellrc" <<'PROMPT_EOF'

# GHOST_OGGUN_PROMPT - solo en terminal interactiva BSPWM
if [[ -o interactive && ${DESKTOP_SESSION:-} == *bspwm* ]]; then
  PROMPT='%F{green}[%n@iron-forge]%f-[%~]%# '
fi
PROMPT_EOF
    fi
  fi
done

cat > "$BACKUP/restaurar.sh" <<'RESTORE_EOF'
#!/usr/bin/env bash
set -eu
base="$(cd -- "$(dirname -- "$0")" && pwd)"
find "$base" -type f -o -type l | while IFS= read -r f; do
  [[ "$f" == "$base/restaurar.sh" ]] && continue
  rel="${f#"$base"/}"
  mkdir -p "$HOME/$(dirname "$rel")"
  cp -a --remove-destination -- "$f" "$HOME/$rel"
done
echo 'Configuración previa restaurada. Los archivos nuevos y paquetes instalados se conservan. Cierra sesión para aplicar.'
RESTORE_EOF
chmod 755 "$BACKUP/restaurar.sh"

# GHOST OGGUN 4.1: material de estudio local, no necesita internet.
DESK="$(xdg-user-dir DESKTOP 2>/dev/null || true)"
[[ -n "$DESK" && "$DESK" != "$HOME" && "$DESK" == "$HOME/"* ]] || DESK="$HOME/Desktop"
mkdir -p "$DESK"
BOOK="$DESK/Libro Maestro 4.3 - Linux y Ciberseguridad.pdf"
backup_file "$BOOK"
book_tmp="$(mktemp "$DESK/.ghost-book.XXXXXX")"
